tool_calls:
awk '
FNR == NR { p=index($0,"="); if (p) { k=substr($0,1,p-1); old[k]=substr($0,p+1); oldkeys[++n]=k } next }
{ p=index($0,"="); if (p) { k=substr($0,1,p-1); new[k]=substr($0,p+1); newkeys[++m]=k } }
END {
 print "Added keys:";
 for(i=1;i<=m;i++) { k=newkeys[i]; if(!(k in old)) print "  " k " = " new[k] }
 print "\nRemoved keys:";
 for(i=1;i<=n;i++) { k=oldkeys[i]; if(!(k in new)) print "  " k " (was " old[k] ")" }
 print "\nChanged values:";
 for(i=1;i<=n;i++) { k=oldkeys[i]; if(k in new && old[k]!=new[k]) print "  " k ": " old[k] " -> " new[k] }
}' /data/v1.conf /data/v2.conf

